const s = readline();
const n = parseInt(readline());
const regexString = [];
for (let i = 0; i < n; i++) {
    const x = readline();
    // Lookbehind and Lookahead search
    regexString[i] = `(?<=${x})|(?=${x})`;
}

const regex = new RegExp(regexString.join("|"));

console.log(s.split(regex).map(x=>`"${x}"`).join(", "));

